'use client';

import React, { useEffect, useState } from 'react';
import { Breadcrumbs } from '../../components/Breadcrumbs';
import styles from './FavoritesPage.module.scss';
import { Product } from '@/types/ProductType';
import { ProductCard } from '@/components/ProductCard';
import { ProductsList } from '@/components/ProductsList';

const startForm = {
  category: '',
  itemId: '',
  price: '',
  image: '',
  name: '',
  screen: '',
  ram: '',
  camera: '',
  color: '',
  year: '',
  colorsAvailable: '',
  capacityAvailable: '',
};

export const Prisma = () => {
  const [mounted, setMounted] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [category, setCategory] = useState<'products' | 'phones' | 'tablets'>('products');
  const [selectedFile, setSelectedFile] = useState([]);
  const [loading, setLoading] = useState(false);

  console.log(products);

  const [form, setForm] = useState({ ...startForm });

  useEffect(() => {
    setMounted(true);

    const fetchProducts = async () => {
      try {
        const res = await fetch(`/api/products?category=${category}`);
        const data = await res.json();

        if (!res.ok) {
          console.error('Server response:', data);
          throw new Error(`HTTP error! status: ${res.status}`);
        }

        setProducts(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error('Fetch error:', err);
        setProducts([]);
      }
    };

    fetchProducts();
  }, [category]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);

    if (!selectedFile) return alert('Вибери файл');

    const imageUrls = await uploadImages(selectedFile);

    const payload: any = {
      itemId: form.itemId,
      category: form.category,
      name: form.name,
      fullPrice: Number(form.price) || 0,
      price: Number(form.price) || 0,
      screen: form.screen || '',
      capacity: form.screen || '',
      color: form.color || '',
      ram: form.ram || '',
      year: form.year || 2000,
      image: imageUrls[0],
    };

    if (form.category) {
      payload.details = {
        name: form.name,
        screen: form.screen || 'unknown',
        ram: form.ram || 'unknown',
        camera: form.camera || 'unknown',
        resolution: 'unknown',
        processor: 'unknown',
        // zoom: 'unknown',
        capacity: form.capacityAvailable.split(',').map((s) => s.trim()) || [],
        priceRegular: Number(form.price) || 0,
        priceDiscount: Number(form.price) || 0,
        color: form.color || '',
        images: imageUrls,
        cell: [],
        capacityAvailable: form.capacityAvailable.split(',').map((s) => s.trim()) || [],
        colorsAvailable: form.colorsAvailable.split(',').map((s) => s.trim()) || [],
        description: [
          {
            title: 'Always-On Retina display',
            text: [
              'A transformative triple-camera system that adds tons of capability without complexity.An unprecedented leap in battery life.',
              'And a mind-blowing chip that doubles down on machine learning and pushes the boundaries of what a smartphone can do. Welcome to the first iPhone powerful enough to be called Pro.',
            ],
          },
        ],
        namespaceId: '',
      };
    }

    try {
      const res = await fetch('/api/products', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const data = await res.json();
      if (!res.ok) {
        console.error('Server response:', data);
        throw new Error(`HTTP error! status: ${res.status}`);
      }

      setProducts((prev) => [data.product, ...prev]);
      setForm({ ...startForm });
    } catch (err) {
      console.error('Error creating product:', err);
    } finally {
      setLoading(false);
    }
  };

  async function uploadImages(files: File[]) {
    const urls: string[] = [];

    for (const file of files) {
      const reader = new FileReader();

      const url = await new Promise<string>((resolve, reject) => {
        reader.onloadend = async () => {
          const base64 = reader.result;

          try {
            const res = await fetch('/api/upload', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ file: base64 }),
            });

            if (!res.ok) {
              reject(`Upload failed for ${file.name}`);
              return;
            }

            const data = await res.json();
            resolve(data.url);
          } catch (err) {
            reject(err);
          }
        };

        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      urls.push(url);
    }

    return urls;
  }

  return (
    <div className='container'>
      <Breadcrumbs />
      <div className={styles.productsGrid}>
        {!loading &&
          products.map((product) => (
            // <div key={product.id} className={styles.productCard}>
            //   <h3>{product.name}</h3>
            //   <h3>{product.productId}</h3>
            //   <p>${product.price}</p>
            //   <p>${product.category}</p>
            // </div>
            <ProductCard product={product} />
          ))}

					<ProductsList products={products} />
      </div>

      <section className='section'>
        <form onSubmit={handleSubmit}>
          <input
            name='itemId'
            placeholder='Item ID'
            value={form.itemId}
            onChange={handleChange}
            required
          />
          <input name='name' placeholder='Name' value={form.name} onChange={handleChange} />
          <input
            name='price'
            placeholder='Price'
            type='number'
            value={form.price}
            onChange={handleChange}
          />
          <input
            type='file'
            multiple
            accept='image/*'
            onChange={(e) => setSelectedFile(e.target.files)}
          />
          <input
            name='category'
            placeholder='Category'
            value={form.category}
            onChange={handleChange}
          />
          <textarea name='name' placeholder='name' value={form.name} onChange={handleChange} />

          <input name='screen' placeholder='Screen' value={form.screen} onChange={handleChange} />
          <input name='ram' placeholder='RAM' value={form.ram} onChange={handleChange} />
          <input name='camera' placeholder='Camera' value={form.camera} onChange={handleChange} />
          <input
            name='capacityAvailable'
            placeholder='Capacities'
            value={form.capacityAvailable}
            onChange={handleChange}
          />
          <input
            name='colorsAvailable'
            placeholder='Colors'
            value={form.colorsAvailable}
            onChange={handleChange}
          />

          <button type='submit'>Add Product</button>
        </form>
      </section>
    </div>
  );
};

export default Prisma;
